import { db, storage, json, error, isAppDatabaseError, type RouterContext } from '@appdeploy/sdk';

export const BACKUP_TABLES = [
  'radar_admin_verification_queue',
  'radar_admin_verification_control',
  'radar_review_inbox',
  'growth_commercial_metrics', 'growth_commercial_events', 'growth_commercial_config', 'growth_trial_entitlements', 'growth_commercial_audit', 'growth_house_config', 'growth_house_metrics', 'growth_house_events', 'community_posts', 'free_public_run_leases', 'free_public_source_reads', 'free_public_source_runs',
  'growth_advertiser_leads', 'growth_campaigns', 'growth_social_queue', 'hard_exa_cursor', 'motor3_web_cursor',
  'notification_dispatch_log', 'notification_dispatch_state', 'notification_preferences',
  'tc_local_directory_v1', 'tc_local_reviews_v1', 'tc_local_reports_v1',
  'public_feed_last_good',
  'public_feed_build_state', 'public_feed_changes', 'public_feed_control', 'public_feed_identity_policy',
  'public_feed_manifests', 'public_feed_versions', 'radar_candidates', 'radar_document_revalidation_receipts',
  'radar_document_revalidation_state', 'radar_empty_recovery', 'radar_enrichment_cursor',
  'radar_external_pull_state', 'radar_jobs', 'radar_live_tests', 'radar_local_contact_rechecks',
  'radar_meta', 'radar_social_recovery_cursor', 'radar_sources', 'radar_verification_cursor',
  'security_request_limits', 'chatgpt_import_receipts', 'motor_d_import_receipts',
  'social_capture_runs', 'social_notice_evidence', 'source_audits', 'source_meta', 'source_scan_state'
];

export function backupTableAllowed(table: unknown): table is string {
  return typeof table === 'string' && (BACKUP_TABLES.includes(table) || /^radar_external_[a-f0-9]{32}$/.test(table) || /^public_feed_page_[0-9]{1,8}$/.test(table));
}

function privateResponse(data: unknown) {
  const response = json(data);
  response.headers = { ...response.headers, 'Cache-Control': 'no-store, private', 'Vary': 'Authorization', 'X-Content-Type-Options': 'nosniff' };
  return response;
}

// Mounted only after requireAuth + requireAdminEmailAllowlist in index.ts.
// Reads one bounded page or one object. No writes, retries or growing-table drain.
async function readBackupPage(ctx: RouterContext) {
  const body = (ctx.body || {}) as Record<string, unknown>;
  if (body.kind === 'scope') return privateResponse({ tables: BACKUP_TABLES, revision: 'application-backup-v2', consistency: 'rolling_non_atomic', fullPlatformBackup: false, restoreValidated: false, warning: 'Exportación parcial paginada; no es un respaldo restaurable verificado. Conservar todos los cursores y validar restauración en entorno aislado.' });
  const cursor = body.cursor;
  if (cursor !== undefined && cursor !== null && (typeof cursor !== 'string' || cursor.length > 16000)) return error('Cursor inválido.', 400);
  const options = { limit: 5, ...(typeof cursor === 'string' && cursor ? { nextToken: cursor } : {}) };
  if (body.kind === 'table') {
    if (!backupTableAllowed(body.table)) return error('Tabla fuera del ámbito autorizado.', 400);
    const page = await db.list(body.table, options);
    if (Buffer.byteLength(JSON.stringify(page), 'utf8') > 1500000) return error('Página demasiado grande para una descarga segura.', 413);
    return privateResponse({ kind: 'table', table: body.table, items: page.items, nextToken: page.nextToken || null });
  }
  if (body.kind === 'storage') {
    const page = await storage.list({ ...options, limit: 5 });
    if (Buffer.byteLength(JSON.stringify(page), 'utf8') > 1500000) return error('Página de archivos demasiado grande.', 413);
    return privateResponse({ kind: 'storage', paths: page.paths, nextToken: page.nextToken || null });
  }
  if (body.kind === 'file' || body.kind === 'file-status') {
    const path = body.path;
    if (typeof path !== 'string' || !path || path.length > 1024 || path.startsWith('/') || path.includes('\\') || path.split('/').some(part => !part || part === '..' || part === '.')) return error('Ruta inválida.', 400);
    const [file] = await storage.read([path]);
    if (body.kind === 'file-status') return privateResponse({ kind: 'file-status', available: Boolean(file && file.path === path && typeof file.content === 'string'), bytes: file?.content === null || file?.content === undefined ? null : Buffer.byteLength(file.content, 'utf8') });
    if (!file || file.path !== path || file.content === null) return error('El archivo no está disponible. La copia está incompleta.', 409);
    if (Buffer.byteLength(file.content, 'utf8') > 1500000) return error('Archivo demasiado grande para este exportador. Requiere respaldo de plataforma.', 413);
    return privateResponse({ kind: 'file', path, content: file.content });
  }
  return error('Operación de respaldo inválida.', 400);
}

export async function adminBackupPage(ctx: RouterContext) {
  try {
    return await readBackupPage(ctx);
  } catch (cause: unknown) {
    const code = isAppDatabaseError(cause) ? cause.code : 'UnknownReadFailure';
    const quota = code === 'AppDatabaseQuotaExceeded';
    const incomplete = code === 'AppDatabaseReadIncomplete';
    const body = (ctx.body || {}) as Record<string, unknown>;
    console.warn('backup_export_read_failed', {
      kind: ['scope','table','storage','file','file-status'].includes(String(body.kind)) ? body.kind : 'unknown',
      table: backupTableAllowed(body.table) ? body.table : undefined,
      code
    });
    const response = json({ error: quota ? 'Cuota de lectura alcanzada.' : 'No se completó la lectura del respaldo.', code: quota ? 'backup_quota' : incomplete ? 'backup_read_incomplete' : 'backup_read_failed' }, quota ? 429 : 503);
    response.headers = { ...response.headers, 'Cache-Control': 'no-store, private', 'Vary': 'Authorization' };
    return response;
  }
}

import {db, secrets} from '@appdeploy/sdk';
import {Buffer} from 'node:buffer';
import {directChatGPTImport} from './chatgpt-direct-import';
import {readPublicFeedPage} from './public-feed';

// Independent GitHub intake. Never reads Motor D's index or receipts.
const REPO='mrvvergara-afk/Trabajo-Cerca-';
const ROOT='automation/chatgpt_ready/';
const INDEX=ROOT+'index.json';
type Result={id:string;status:string;internalId?:string;existingId?:string;expectedWorkCommunes?:string[]};
type Receipt={id:string;batchId:string;status:string;results:Result[];newCount:number;published:number;at:string;checkedAt?:string};

async function load(path:string,token:string){
  if(path!==INDEX&&!/^automation\/chatgpt_ready\/\d{8}\/chatgpt-\d{8}-[a-f0-9]{18}\.json$/.test(path))
    throw Error('unsafe_chatgpt_path');
  const response=await fetch('https://api.github.com/repos/'+REPO+'/contents/'+path+'?ref=main',{
    headers:{authorization:'Bearer '+token,accept:'application/vnd.github+json',
      'x-github-api-version':'2022-11-28','user-agent':'TrabajoCerca-ChatGPT-Publisher'},
    signal:AbortSignal.timeout(9000)
  });
  if(response.status===404)return null;
  if(!response.ok)throw Error('chatgpt_github_http_'+response.status);
  const raw=await response.json() as {encoding?:string;content?:string;size?:number;sha?:string};
  if(raw.encoding!=='base64'||!raw.content||!raw.size||raw.size>180000||!raw.sha)
    throw Error('chatgpt_invalid_content');
  const bytes=Buffer.from(raw.content.replace(/\s/g,''),'base64');
  if(bytes.length!==raw.size)throw Error('chatgpt_size_mismatch');
  return {data:JSON.parse(bytes.toString('utf8')) as Record<string,unknown>,sha:raw.sha};
}
function result(state:string,extra:Record<string,unknown>={}){
  const row={at:new Date().toISOString(),state,...extra};
  console.warn('CHATGPT_BRIDGE '+JSON.stringify(row).slice(0,5000));
  return {statusCode:200,body:JSON.stringify(row)};
}
export async function chatgptAutoImportHandler(){
  try{
    if(!(await secrets.listSecretNames()).includes('MOTOR_C_GITHUB_READ_TOKEN'))
      return result('awaiting_github_read_token');
    const token=await secrets.readSecret('MOTOR_C_GITHUB_READ_TOKEN');
    const head=await load(INDEX,token);
    if(!head)return result('awaiting_chatgpt_index');
    const idx=head.data;
    if(idx.schema_version!==1||idx.producer!=='chatgpt_territorial'||
       !Array.isArray(idx.batches)||idx.batches.length>256)return result('invalid_chatgpt_index');
    let processed=0;
    for(const entry of idx.batches as Array<Record<string,unknown>>){
      const batchId=String(entry.batch_id||'');
      const rel=String(entry.file||'');
      if(!/^chatgpt-\d{8}-[a-f0-9]{18}$/.test(batchId)||
         !/^\d{8}\/chatgpt-\d{8}-[a-f0-9]{18}\.json$/.test(rel)||
         !rel.endsWith('/'+batchId+'.json'))return result('invalid_chatgpt_reference',{batchId});
      const [old]=await db.get<Receipt>('chatgpt_import_receipts',[batchId],{consistent:true});
      if(old?.results?.length){processed++;continue;}
      const file=await load(ROOT+rel,token);
      if(!file)return result('missing_chatgpt_batch',{batchId});
      const batch=file.data;
      if(batch.schema_version!==1||batch.producer!=='chatgpt_territorial'||
         batch.approval!=='approved_for_publication'||batch.batch_id!==batchId||
         !Array.isArray(batch.offers)||!batch.offers.length||batch.offers.length>15)
        return result('unapproved_chatgpt_batch',{batchId});
      const offers=batch.offers as Array<Record<string,unknown>>;
      if(offers.some(x=>typeof x.id_fuente!=='string'||!/^cg_[a-f0-9]{20}$/.test(x.id_fuente)))
        return result('invalid_chatgpt_offer_ids',{batchId});
      const output=await directChatGPTImport({offers,commit:true,producer:'chatgpt_territorial'});
      if(output.statusCode!==200)return result('chatgpt_import_error',{batchId,http:output.statusCode});
      const parsed=JSON.parse(String(output.body||'{}')) as {results?:Result[]};
      const results=parsed.results||[];
      const expected=new Set(offers.map(x=>String(x.id_fuente)));
      if(results.length!==offers.length||expected.size!==offers.length||
         new Set(results.map(x=>x.id)).size!==offers.length||results.some(x=>!expected.has(x.id)))
        return result('chatgpt_receipt_mismatch',{batchId});
      const allowed=new Set(['direct_record_queued_for_public_projection','already_published',
        'already_imported_id','expired','review_expired','territory_reconciled']);
      if(results.some(x=>!allowed.has(x.status)))return result('chatgpt_unexpected_import_result',{batchId});
      const newCount=results.filter(x=>x.status==='direct_record_queued_for_public_projection'||x.status==='territory_reconciled').length;
      const receipt:Receipt={id:batchId,batchId,status:newCount?'awaiting_public_feed':'processed_without_new_publications',
        results,newCount,published:0,at:new Date().toISOString()};
      try{
        const [saved]=await db.tx.add('chatgpt_import_receipts',[receipt]);
        if(!saved)throw Error('chatgpt_receipt_write_unconfirmed');
      }catch(cause){
        const [again]=await db.get<Receipt>('chatgpt_import_receipts',[batchId],{consistent:true});
        if(!again?.results?.length)throw cause;
      }
      return result('chatgpt_imported_waiting_for_feed',{batchId,newCount,duplicates:results.length-newCount});
    }
    const latestBatch = (idx.batches as Array<Record<string,unknown>>)
      .map(entry => String(entry.batch_id || ''))
      .sort()
      .at(-1) || '';
    const latestBatchDate = /^chatgpt-\d{8}-[a-f0-9]{18}$/.test(latestBatch)
      ? latestBatch.slice(8,12) + '-' + latestBatch.slice(12,14) + '-' + latestBatch.slice(14,16)
      : null;
    const lastBatchAgeHours = latestBatchDate
      ? Math.max(0, Math.floor((Date.now() - Date.parse(latestBatchDate + 'T23:59:59-03:00')) / 3600000))
      : null;
    const producerStale = lastBatchAgeHours === null || lastBatchAgeHours >= 24;
    return result(producerStale ? 'producer_stale_no_new_batches' : 'no_unprocessed_chatgpt_batches', {
      indexedBatches:idx.batches.length,
      processed,
      latestBatchDate,
      lastBatchAgeHours,
      producerStale,
      actionRequired:producerStale ? 'check_scheduled_chatgpt_producer' : null,
    });
  }catch(cause){
    return result('chatgpt_bridge_error',{error:String(cause).slice(0,180)});
  }
}
export async function confirmChatGPTPublications(){
  try{
    const pending:Receipt[]=[];
    let token:string|undefined;
    const receiptCursors=new Set<string>();
    let receiptsComplete=false;
    for(let n=0;n<100;n++){
      const page=await db.list<Receipt>('chatgpt_import_receipts',{limit:100,...(token?{nextToken:token}:{})});
      pending.push(...page.items.filter(x=>x.status==='awaiting_public_feed'&&x.newCount>0));
      if(!page.nextToken){receiptsComplete=true;break;}
      if(receiptCursors.has(page.nextToken))break;
      receiptCursors.add(page.nextToken);token=page.nextToken;
    }
    if(!receiptsComplete)return {status:'receipts_incomplete',checked:0,published:0};
    if(!pending.length)return {status:'idle',checked:0,published:0};
    const ids=new Set<string>();
    const workById=new Map<string,string[]>();
    let cursor:string|undefined,complete=false,total=0;
    const seen=new Set<string>();
    for(let n=0;n<100;n++){
      const page=await readPublicFeedPage(cursor);
      if(!page||('feedRebuilding' in page && page.feedRebuilding===true)||('degraded' in page && page.degraded===true))return {status:'feed_unavailable',checked:0,published:0};
      if(!Array.isArray(page.items))return {status:'feed_invalid_items',checked:0,published:0};
      total+=page.items.length;
      for(const item of page.items){
        const id=String(item.id);ids.add(id);
        workById.set(id,Array.isArray(item.workCommunes)?item.workCommunes as string[]:[]);
      }
      if(!page.nextCursor){complete=total>=Number(page.totalJobOffers||0);break;}
      if(seen.has(page.nextCursor))break;
      seen.add(page.nextCursor);cursor=page.nextCursor;
    }
    if(!complete)return {status:'feed_incomplete',checked:0,published:0};
    let published=0;
    for(const receipt of pending.slice(0,12)){
      const newer=receipt.results.filter(x=>x.status==='direct_record_queued_for_public_projection'||x.status==='territory_reconciled');
      const count=newer.filter(x=>{
        const key=x.internalId||('chatgpt_'+x.id);
        if(!ids.has(key))return false;
        if(!x.expectedWorkCommunes?.length)return true;
        const sites=workById.get(key)||[];
        return x.expectedWorkCommunes.every(site=>sites.includes(site));
      }).length;
      await db.tx.update('chatgpt_import_receipts',[{id:receipt.id,record:{
        ...receipt,published:count,status:count===newer.length?'published':'awaiting_public_feed',
        checkedAt:new Date().toISOString()
      }}]);
      published+=count;
    }
    return {status:'checked',checked:Math.min(12,pending.length),published};
  }catch(cause){return {status:'confirmation_error',error:String(cause).slice(0,180),checked:0,published:0};}
}

import { municipalOfferStatusFromHtml } from './municipal-index-status';
import {canonicalSourceUrl,canonicalSourceHash} from './chatgpt-url-identity';
import { db, json, error, isAppDatabaseError } from '@appdeploy/sdk';
import { readPublicFeedPage, registerPublicFeedChange } from './public-feed';
import { safePublicUrl, publicJobExclusion, publicFeedIdentity } from './public-source-adapters';
import { worksiteMentionsCommune } from './worksite-semantics';

type Candidate={id_fuente:string;cargo:string;empresa:string;comunas:string[];url_original:string;fecha_publicacion:string|null;fecha_descubrimiento?:string;municipal_open_index_url?:string;application_method?:string;fecha_cierre?:string|null;vigencia_fuente?:string;fecha_verificacion?:string;justificacion?:string;recruitment_communes?:string[];work_location?:string;territorial_recruitment_verified?:boolean;social_source_account?:string;social_evidence_type?:string;fecha_publicacion_metodo?:string;internal_visibility_days?:number;ubicacion_trabajo?:string;modalidad?:string;salario?:string|null;enlace_postulacion?:string|null;url_canonica?:string;hash_url_sha256?:string};
const LOCAL=new Set(['Angol','Collipulli','Ercilla','Lumaco','Los Sauces','Purén','Renaico','Traiguén','Victoria','Mulchén','Negrete','Nacimiento']);
const norm=(s:string)=>s.toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g,' ').replace(/ +/g,' ').trim();
const keyUrl=(s:string)=>{const known=publicFeedIdentity(s);if(known)return known;const clean=safePublicUrl(s);if(!clean)return '';const url=new URL(clean);return url.hostname.replace(/^www\./,'')+url.pathname.replace(/\/$/,'')+url.search;};
const stableJobIdentity=(s:string)=>{
  try{
    const url=new URL(s);
    if(!['www.chiletrabajos.cl','chiletrabajos.cl'].includes(url.hostname.toLowerCase()))return '';
    const m=url.pathname.match(/^\/trabajo\/(?:[^/]*-)?(\d{5,12})\/?$/);
    return m?'ct:'+m[1]:'';
  }catch{return '';}
};
const STRICT_FIELDS=new Set(['id_fuente','cargo','empresa','comunas','ubicacion_trabajo',
  'modalidad','salario','url_original','enlace_postulacion','fecha_publicacion','fecha_descubrimiento',
  'fecha_cierre','justificacion','url_canonica','hash_url_sha256','vigencia_fuente','fecha_verificacion']);
const REQUIRED_STRICT=['id_fuente','cargo','empresa','comunas','ubicacion_trabajo',
  'modalidad','salario','url_original','enlace_postulacion','fecha_publicacion','fecha_descubrimiento'];
function territoryFromLocation(name:string,work:string){
  return worksiteMentionsCommune(work,name);
}
function parse(value:unknown,strict=false):Candidate[]|null {
  if(!Array.isArray(value)||value.length<1||value.length>15)return null;
  const result:Candidate[]=[];
  for(const input of value){
    if(!input||typeof input!=='object')return null;
    const x=input as Record<string,unknown>;
    const id=String(x.id_fuente??''), title=String(x.cargo??''), company=String(x.empresa??''),url=String(x.url_original??'');
    const communes=x.comunas;
    const date=x.fecha_publicacion==null?null:String(x.fecha_publicacion),deadline=x.fecha_cierre==null?null:String(x.fecha_cierre);
    // The publisher did not specify the original date. No fabricated date
    // or artificial employer deadline; allow only the exact official OMIL proof.
    const verifiedDay=String(x.fecha_verificacion||'');
    const evidenceAt=/^20\d{2}-\d{2}-\d{2}$/.test(verifiedDay)
      ? Date.parse(verifiedDay+'T00:00:00-03:00'):NaN;
    const strictUndatedOpen=Boolean(strict && date===null &&
      x.vigencia_fuente==='postulacion_abierta_verificada' &&
      Number.isFinite(evidenceAt) && evidenceAt<=Date.now() &&
      Date.now()-evidenceAt<=3*86400000 &&
      typeof x.enlace_postulacion==='string' &&
      Boolean(safePublicUrl(x.enlace_postulacion)));
    const municipalOpen=(date===null &&
      url==='https://www.munimulchen.cl/oferta-laboral-02-operarios-agrarios-cosecha-de-arandanos/' &&
      x.municipal_open_index_url==='https://www.munimulchen.cl/pagina-central-ofertas-laborales/' &&
      x.fecha_publicacion_metodo==='original_no_informada_municipal_abierta' &&
      x.application_method==='in_person_omil' && x.internal_visibility_days===14 &&
      x.comunas instanceof Array && x.comunas.length===1 && x.comunas[0]==='Mulchén' &&
      x.empresa==='Empresa agrícola no identificada (OMIL Mulchén)' &&
      typeof x.fecha_descubrimiento==='string' &&
      /^20\d{2}-\d{2}-\d{2}$/.test(x.fecha_descubrimiento) &&
      Number.isFinite(Date.parse(x.fecha_descubrimiento)) &&
      Date.parse(x.fecha_descubrimiento)<=Date.now());
    if(!/^[A-Za-z0-9_-]{4,64}$/.test(id)||title.length<5||title.length>180||company.length<2||company.length>140||
      !Array.isArray(communes)||!communes.length||communes.length>12||!communes.every(y=>typeof y==='string'&&LOCAL.has(y))||
      (!municipalOpen && !strictUndatedOpen && (date===null || !/^20[0-9]{2}-[0-9]{2}-[0-9]{2}$/.test(date) || Number.isNaN(Date.parse(date)) || Date.parse(date+'T00:00:00-03:00')>Date.now()))||
      (deadline!==null&&(!/^20[0-9]{2}-[0-9]{2}-[0-9]{2}$/.test(deadline)||Number.isNaN(Date.parse(deadline))))||
      !url.startsWith('https://')||url.length>700)return null;
    // A brand in the title (Forestal Mininco, Paneles Arauco) is NOT a
    // worksite. Only a separately identified place of work can justify a
    // commune. Missing worksite evidence remains for review rather than
    // forcing Collipulli or silently accepting a contrary commune.
    if(typeof x.ubicacion_trabajo==='string' &&
       !(communes as string[]).every(city =>
         territoryFromLocation(city,String(x.ubicacion_trabajo)))) return null;
    let host='';try{host=new URL(url).hostname.toLowerCase()}catch{return null;}
    const omilSocial=(host==='www.instagram.com'||host==='instagram.com')&&new URL(url).pathname.replace(/\/$/,'')==='/omilangol2026'&&
      x.social_source_account==='omilangol2026'&&x.social_evidence_type==='user_supplied_official_omil_post_and_poster_screenshots'&&
      x.territorial_recruitment_verified===true&&Array.isArray(x.recruitment_communes)&&
      x.recruitment_communes.length===1&&x.recruitment_communes[0]==='Angol'&&
      Number(x.internal_visibility_days)>=1&&Number(x.internal_visibility_days)<=15&&
      typeof x.fecha_publicacion_metodo==='string'&&x.fecha_publicacion_metodo.startsWith('fecha_inferida_');
    if(!omilSocial && (!safePublicUrl(url) || publicJobExclusion({kind:'job_offer',url,title,workCommunes:communes})))return null;
    if(strict){
      if(Object.keys(x).some(k=>!STRICT_FIELDS.has(k))||REQUIRED_STRICT.some(k=>!(k in x))||
        !/^cg_[a-f0-9]{20}$/.test(id)||typeof x.ubicacion_trabajo!=='string'||
        x.ubicacion_trabajo.trim().length<3||x.ubicacion_trabajo.length>240||
        !Array.isArray(communes)||!(communes as string[]).every(c=>territoryFromLocation(c,String(x.ubicacion_trabajo)))||
        !['presencial','hibrida','remota','no_informada'].includes(String(x.modalidad))||
        !(x.salario===null||(typeof x.salario==='string'&&x.salario.length>=1&&x.salario.length<=100))||
        !(x.enlace_postulacion===null||(typeof x.enlace_postulacion==='string'&&Boolean(safePublicUrl(x.enlace_postulacion))))||
        typeof x.fecha_descubrimiento!=='string'||!/^20\d{2}-\d{2}-\d{2}$/.test(x.fecha_descubrimiento)||
        Number.isNaN(Date.parse(x.fecha_descubrimiento))||
        Date.parse(x.fecha_descubrimiento+'T00:00:00-03:00')>Date.now()||
        date!==null&&x.fecha_descubrimiento<date)return null;
      try{
        if(x.url_canonica!==canonicalSourceUrl(url)||x.hash_url_sha256!==canonicalSourceHash(url))return null;
      }catch{return null;}
    }
    result.push({id_fuente:id,cargo:title,empresa:company,comunas:[...new Set(communes as string[])],url_original:url,fecha_publicacion:date,fecha_cierre:deadline,justificacion:String(x.justificacion??'').slice(0,500),
      ...(strict?{ubicacion_trabajo:String(x.ubicacion_trabajo),modalidad:String(x.modalidad),
        salario:x.salario as string|null,enlace_postulacion:x.enlace_postulacion as string|null,
        url_canonica:String(x.url_canonica),hash_url_sha256:String(x.hash_url_sha256),
        fecha_descubrimiento:String(x.fecha_descubrimiento)}:{}),
      ...(strictUndatedOpen?{vigencia_fuente:'postulacion_abierta_verificada',
        fecha_verificacion:verifiedDay}:{}),...(municipalOpen?{
